<div class="page-actions"><div><p class="mb-0">Quotation dengan item jasa/material, approval, dan konversi ke Job Order.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#quoteModal"><i class="bi bi-plus-lg"></i> New Quotation</button></div>
<div class="card-panel"><div class="table-responsive"><table class="table align-middle datatable"><thead><tr><th>Quotation</th><th>Customer</th><th>Date</th><th>Valid Until</th><th>Status</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($quotations as $q): ?><tr><td><a href="<?= url('/quotations/'.$q['id']) ?>"><strong><?= e($q['quotation_number']) ?></strong></a></td><td><?= e($q['customer_name']) ?></td><td><?= e($q['quotation_date']) ?></td><td><?= e($q['valid_until']??'-') ?></td><td><span class="status-badge <?= $q['status']==='Approved'?'success':'' ?>"><?= e($q['status']) ?></span></td><td><?= e(money($q['grand_total'])) ?></td><td class="text-end"><a class="btn btn-sm btn-light" href="<?= url('/quotations/'.$q['id']) ?>"><i class="bi bi-eye"></i></a></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="modal fade" id="quoteModal"><div class="modal-dialog modal-xl"><form class="modal-content ajax-form" method="post" action="<?= url('/quotations') ?>"><?= csrf_field() ?><div class="modal-header"><h5>New Quotation</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3 mb-3"><div class="col-md-6"><label class="form-label">Customer</label><select class="form-select" name="customer_id" required><option value="">Select</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Valid Until</label><input class="form-control" type="date" name="valid_until" value="<?= date('Y-m-d',strtotime('+14 days')) ?>"></div></div><div class="table-responsive"><table class="table quote-items"><thead><tr><th>Type</th><th>Description</th><th>Qty</th><th>Unit</th><th>Unit Price</th><th>Discount</th><th>Tax</th><th></th></tr></thead><tbody id="quoteItemBody"></tbody></table></div><button class="btn btn-sm btn-outline-primary" type="button" id="addQuoteItem"><i class="bi bi-plus"></i> Add Item</button><div class="row g-3 mt-2"><div class="col-md-6"><label class="form-label">Terms</label><textarea class="form-control" name="terms" rows="2"></textarea></div><div class="col-md-6"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="2"></textarea></div></div></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Create Quotation</button></div></form></div></div>
<template id="quoteItemTpl"><tr><td><select class="form-select" data-name="item_type"><option value="service">Service</option><option value="material">Material</option><option value="other">Other</option></select></td><td><input class="form-control" data-name="description" required></td><td><input class="form-control" type="number" step="0.01" value="1" data-name="quantity" required></td><td><input class="form-control" value="job" data-name="unit"></td><td><input class="form-control" type="number" step="0.01" value="0" data-name="unit_price"></td><td><input class="form-control" type="number" step="0.01" value="0" data-name="discount"></td><td><input class="form-control" type="number" step="0.01" value="0" data-name="tax"></td><td><button type="button" class="btn btn-sm btn-light text-danger remove-row"><i class="bi bi-trash"></i></button></td></tr></template>
